contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this) && actor != address(0) && actor != address(c));
        address currentOwner = c.owner();
        vm.prank(actor);
        try c.setOwner(newOwner) {
            // call succeeded
        } catch {
            // call reverted
        }
        assertTrue(
            (actor == currentOwner) == (c.owner() == newOwner) &&
            (actor != currentOwner || c.owner() == newOwner),
            "non-owner must not be able to change owner"
        );
    }
}

