pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address candidate) public {
        // WIDE admissible domain: any candidate owner is allowed except values that
        // would coincide with the caller (the deployer/test contract) or the zero address.
        vm.assume(candidate != address(this));
        vm.assume(candidate != address(0));

        // The test contract is the initial owner, so it may call setOwner directly.
        // Rule: a successful ownership transfer must set owner EXACTLY to the
        // requested candidate, not to the caller (msg.sender).
        c.setOwner(candidate);

        assertTrue(c.owner() == candidate);
    }
}

