pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // admissible domain: the new owner must differ from the current owner (the test contract)
        vm.assume(newOwner != address(this));

        // 1) current owner transfers ownership to a fuzzed distinct address
        vm.prank(address(this));
        c.setOwner(newOwner);

        // 2) the original owner attempts a further ownership action
        bool ok;
        vm.prank(address(this));
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // general rule: ownership transfer strips the previous owner of rights,
        // so their follow-up setOwner must revert. The mutant overwrites owner
        // with msg.sender inside the modifier, so the original owner retains
        // rights and the follow-up call succeeds — breaking the rule.
        assertTrue(!ok, "previous owner must lose owner rights after transferring ownership");
    }
}

